import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"hnl_engine_exec_bytecode","description":"","frontmatter":{},"headers":[],"relativePath":"api/engine-exec-bytecode/hnl_engine_exec_bytecode/index.md","filePath":"api/engine-exec-bytecode/hnl_engine_exec_bytecode/index.md"}`),a={name:`api/engine-exec-bytecode/hnl_engine_exec_bytecode/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="hnl-engine-exec-bytecode" tabindex="-1">hnl_engine_exec_bytecode <a class="header-anchor" href="#hnl-engine-exec-bytecode" aria-label="Permalink to “hnl_engine_exec_bytecode”">​</a></h1><h1 id="hnl-engine-exec-bytecode-1" tabindex="-1">hnl-engine-exec-bytecode <a class="header-anchor" href="#hnl-engine-exec-bytecode-1" aria-label="Permalink to “hnl-engine-exec-bytecode”">​</a></h1><p>The <strong>bytecode eval engine</strong> for the eval operation (ADR-0044 §4, §7).</p><p>This engine compiles [<code>handl_language::Term</code>] (the v2 arrow-calculus kernel, ADR-0052) data to a bytecode representation and executes it via a stack-based VM. It shares the same <code>Term</code> vocabulary as the <code>hnl-engine-exec-tree-walk</code> reference interpreter (a dev-dependency); conformance tests verify both produce <strong>identical results</strong>.</p><h2 id="compilers-erase-data-dispatch-adr-0044-§7" tabindex="-1">Compilers erase data dispatch (ADR-0044 §7) <a class="header-anchor" href="#compilers-erase-data-dispatch-adr-0044-§7" aria-label="Permalink to “Compilers erase data dispatch (ADR-0044 §7)”">​</a></h2><p>The tree-walk pays for per-node scheme lookup (<code>lang.eval[node.kind]</code> → <code>Term</code>) on every execution. The bytecode engine <strong>compiles this lookup away</strong>: at compile time, every node kind&#39;s scheme is resolved to a fixed instruction sequence. The compiled artifact has no hash lookups, no string matching, no <code>lang.eval</code> access at execution time.</p><p>A per-node compilation cache (compile each node&#39;s scheme once, cache by [<code>AstRef</code>]) is used to demonstrate this. When [<code>Instr::EvalChild</code>] runs, it looks up the child&#39;s <code>AstRef</code> in the cache; on a miss, it compiles the child&#39;s scheme (one-time <code>lang.eval</code> lookup) and caches the result. On subsequent executions, the cached instructions are reused — no data dispatch occurs. Full ahead-of-time compilation of the whole AST is a future refinement.</p><h2 id="bytecode-isa" tabindex="-1">Bytecode ISA <a class="header-anchor" href="#bytecode-isa" aria-label="Permalink to “Bytecode ISA”">​</a></h2><p>See the [<code>instr</code>] module for the full instruction set documentation. The ISA covers all six <code>Term</code> combinators (<code>Arr</code>, <code>Seq</code>, <code>First</code>, <code>Choice</code>, <code>Loop</code>, <code>App</code>); see the [<code>instr</code>] module&#39;s combinator-to-instruction mapping table for details.</p><h2 id="conventions-matched-to-the-tree-walk" tabindex="-1">Conventions (matched to the tree-walk) <a class="header-anchor" href="#conventions-matched-to-the-tree-walk" aria-label="Permalink to “Conventions (matched to the tree-walk)”">​</a></h2><ul><li><code>proj_child(n)</code> = nth child of current node: reads <code>node.payload[&quot;children&quot;][n]</code> to get the absolute <code>AstRef</code>, then recurses.</li><li><code>proj_env(&quot;$payload&quot;)</code> reads <code>node.payload</code> as the variable name.</li><li><code>extend_env(&quot;$payload&quot;)</code> reads <code>node.payload[&quot;name&quot;]</code> as the bind name.</li><li>No-scheme fallback: if a node kind has no eval scheme, returns <code>node.payload</code> directly.</li><li>Closure representation: <code>Value::Object</code> with <code>{&quot;__arrow__&quot;: true, &quot;params&quot;: [...], &quot;body_def&quot;: {&quot;__ast__&quot;: &amp;lt;arena&gt;}, &quot;binds&quot;: {...}, &quot;handlers&quot;: [...]}</code> — self-contained serializable data (ADR-0106), created by <code>Instr::Closure</code>.</li><li>Native ops: <code>add, sub, mul, div, mod, neg, eq, neq, lt, gt, lte, gte, and, or, not, tag, id, closure, bind</code> — identical semantics to the tree-walk.</li><li>Scope: <code>Vec&lt;HashMap&lt;String, Value&gt;&gt;</code> scope stack; <code>extend_env</code> pushes a child scope; lookup searches innermost-first. Arrow applications install the arrow&#39;s <code>binds</code> as the captured root, bind params, eval the <code>body_def</code> arena, restore.</li></ul><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="hnl-engine-exec-bytecode-2" tabindex="-1"><a href="./hnl_engine_exec_bytecode.html"><code>hnl_engine_exec_bytecode</code></a> <a class="header-anchor" href="#hnl-engine-exec-bytecode-2" aria-label="Permalink to “hnl_engine_exec_bytecode”">​</a></h3><p><em>1 type alias, 3 modules, 3 structs</em></p><h3 id="bytecodeengine" tabindex="-1"><a href="./BytecodeEngine.html"><code>BytecodeEngine</code></a> <a class="header-anchor" href="#bytecodeengine" aria-label="Permalink to “BytecodeEngine”">​</a></h3><p><em>2 functions</em></p><h3 id="compile" tabindex="-1"><a href="./compile.html"><code>compile</code></a> <a class="header-anchor" href="#compile" aria-label="Permalink to “compile”">​</a></h3><p><em>11 functions, 2 structs</em></p><h3 id="instr" tabindex="-1"><a href="./instr.html"><code>instr</code></a> <a class="header-anchor" href="#instr" aria-label="Permalink to “instr”">​</a></h3><p><em>2 enums</em></p><h3 id="vm" tabindex="-1"><a href="./vm.html"><code>vm</code></a> <a class="header-anchor" href="#vm" aria-label="Permalink to “vm”">​</a></h3><p><em>1 type alias, 18 functions, 4 constants, 6 structs</em></p><h3 id="vm-vmframe" tabindex="-1"><a href="./vm/VmFrame.html"><code>vm::VmFrame</code></a> <a class="header-anchor" href="#vm-vmframe" aria-label="Permalink to “vm::VmFrame”">​</a></h3><p><em>1 function</em></p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};